.section-head,.panel:not(.card)>h2{position:relative}.section-head::before,.panel:not(.card)>h2::before{content:"";position:absolute;inset:-.6rem 0 auto;height:2px;background:var(--rk,var(--steel))}
.tabs{padding:0;gap:.375rem;background:none;border:0}.keyset{display:grid;gap:.5rem;padding:.8rem 1rem}.keyset-search{display:flex;gap:.75rem;align-items:flex-end}.keyset-search .field{flex:0 0 auto}.keyset-search .wide{flex:1 1 8rem}.keyset-search .actions{display:flex;gap:.9rem;align-items:center}.keys{display:grid;grid-template-columns:3.4rem minmax(0,1fr);align-items:start}.keys-name{margin:0;padding-top:.95rem;font:500 .8rem/1 var(--sans);color:var(--label)}.key-row{display:flex;flex-wrap:wrap;gap:.375rem}.key{position:relative;display:inline-flex;align-items:center;gap:.45rem;min-height:2.75rem;padding:0 .8rem;font:500 .875rem/1.1 var(--sans);color:var(--secondary);text-decoration:none;background:linear-gradient(180deg,var(--surface-3),var(--surface-2));border:1px solid var(--plate-edge);border-radius:3px;box-shadow:inset 0 1px 0 rgb(255 255 255/.07),0 1px 0 #070a0b;transition:color .15s,border-color .15s}button.key{cursor:pointer}.key:hover{color:var(--heading);border-color:var(--rail-hi)}.key:active{transform:translateY(1px);box-shadow:inset 0 1px 3px rgb(0 0 0/.5)}.key .icon{width:1rem;height:1rem;flex:none;color:var(--kind,var(--label))}a.key[aria-current]{padding-right:1.5rem;color:var(--heading);background:color-mix(in srgb,var(--steel) 20%,#12181d);border-color:var(--rail-hi);box-shadow:inset 0 2px 0 var(--steel),inset 0 -8px 8px -8px #000}a.key[aria-current]::after{content:"";position:absolute;right:.55rem;top:50%;width:6px;height:6px;margin-top:-3px;border-radius:50%;background:var(--lamp-core);box-shadow:var(--lamp-glow)}.head-add{padding:0 1.25rem;box-shadow:inset 0 1px 0 rgb(255 255 255/.3),0 0 0 1px color-mix(in srgb,var(--brand) 45%,transparent),0 0 14px -2px var(--ph-tight),0 8px 26px -10px color-mix(in srgb,var(--brand) 70%,transparent)}@media(max-width:40rem){.keys{grid-template-columns:minmax(0,1fr)}.keys-name{padding:.3rem 0 0}.keyset-search{flex-wrap:wrap}}.ask-question label{display:inline-block;position:relative;clip-path:inset(-1.5em -1.2em -1.5em -1em);animation:q-type .9s steps(20) backwards}.ask-question label::after{content:"";position:absolute;left:calc(100% + .14em);top:.17em;width:.5em;height:.86em;background:color-mix(in srgb,var(--brand) 50%,transparent);animation:q-walk .9s steps(20) backwards}.ask:focus-within .ask-question label::after{background:var(--brand);box-shadow:0 0 8px var(--brand),0 0 18px color-mix(in srgb,var(--brand) 55%,transparent);animation:q-walk .9s steps(20) backwards,q-blink 1.06s steps(1) infinite}@keyframes q-type{from{clip-path:inset(-1.5em calc(100% - 1ch) -1.5em -1em)}}@keyframes q-walk{from{left:0}}@keyframes q-blink{50%{opacity:0}}@media(prefers-reduced-motion:reduce){.ask-question label,.ask-question label::after{animation:none!important}}@media(forced-colors:active){.ask-question label::after{background:CanvasText;box-shadow:none}}.ask-question{font-size:clamp(1.15rem,2vw,1.4rem)}
/* MUT-3 */
/* ---- light: scanlined bloom on the key word; glow kept for what is live ---- */
.glow,.q-mark{--sl-lit:3px;--sl-pitch:5px;--sl-dark:.5}.open-q .glow{--sl-pitch:4.5px;--sl-dark:.4}
.glow{display:inline-block;color:var(--brand);text-shadow:0 0 .3em color-mix(in srgb,var(--halo,var(--brand)) 45%,transparent),0 0 .9em color-mix(in srgb,var(--halo,var(--brand)) 22%,transparent)}
.ask-question .glow,.ask-question .q-mark{font-size:1.75em;font-weight:800;line-height:.7;letter-spacing:-.02em}
.ask-question .glow{margin-left:.04em}
.ask-question .q-mark{display:inline-block;color:var(--brand);opacity:.7;margin-left:.03em}
.open-q .glow{font-weight:700}
@supports ((-webkit-background-clip:text) or (background-clip:text)){
.glow,.q-mark{color:transparent;text-shadow:none;background:repeating-linear-gradient(to bottom,transparent 0 var(--sl-lit),rgb(0 0 0/var(--sl-dark)) var(--sl-lit) var(--sl-pitch)),linear-gradient(180deg,var(--brand-hover) 0,var(--brand) 18%,var(--brand) 50%,color-mix(in srgb,var(--brand) 86%,#0a2a17) 100%);-webkit-background-clip:text;background-clip:text}
.glow{filter:drop-shadow(0 0 .08em color-mix(in srgb,var(--halo,var(--brand)) 65%,transparent)) drop-shadow(0 0 .36em color-mix(in srgb,var(--halo,var(--brand)) 50%,transparent)) drop-shadow(0 0 .9em color-mix(in srgb,var(--halo,var(--brand)) 26%,transparent))}
.q-mark{display:inline-block}
}
.ask-question label{clip-path:inset(-2.2em -1.6em -2.2em -1em)}
.ask-question label::after{top:auto;bottom:.2em;height:1.15em;width:.55em}
/* not live, so matte: the title tile, the bar's current icon, the menu's */
.title-icon:not(.presence),:is(.in-ideas,.in-plans,.in-todo,.in-wishes,.in-family,.in-memory) .title-icon:not(.presence){box-shadow:inset 0 1px 0 color-mix(in srgb,var(--accent) 30%,transparent)}
.title-icon .icon,nav a[aria-current="page"] .icon,.menu.here > summary .icon{filter:none}
@media (prefers-contrast:more){.glow,.q-mark{background:none;color:var(--brand);-webkit-background-clip:border-box;background-clip:border-box;filter:none;text-shadow:none}}
@media print{.glow,.q-mark{background:none;-webkit-background-clip:border-box;background-clip:border-box;color:#0b5a2a;filter:none}}
@media (forced-colors:active){.glow,.q-mark{background:none;color:CanvasText;filter:none;-webkit-background-clip:border-box;background-clip:border-box}}
/* ---- controls: keys in a recessed tray, a lit radio dot, a raised bright Add key ---- */
.key-row{display:inline-flex;flex:0 0 auto;width:fit-content;flex-wrap:wrap;max-width:100%;gap:.25rem;padding:.25rem;background:var(--tray);border:1px solid var(--tray-edge);border-radius:var(--r);box-shadow:inset 0 2px 5px rgb(0 0 0/.6)}
.key,.tabs a.key{border-radius:4px;background:linear-gradient(180deg,#2b353d,#1c242a);border:1px solid #38434c;border-bottom-color:#0b1013;box-shadow:inset 0 1px 0 rgb(255 255 255/.12),0 2px 0 #04070a,0 4px 6px -2px rgb(0 0 0/.7)}
.key:hover,.tabs a.key:hover{color:var(--heading);background:linear-gradient(180deg,#323e47,#202a31);border-color:var(--rail-hi);border-bottom-color:#0b1013}
a.key{padding-right:1.8rem}
a.key::after{content:"";position:absolute;right:.62rem;top:50%;width:9px;height:9px;margin-top:-4.5px;box-sizing:border-box;border-radius:50%;border:1.5px solid var(--rail-hi);background:#0b1013;box-shadow:inset 0 1px 2px rgb(0 0 0/.6)}
a.key[aria-current],.tabs a.key[aria-current]{padding-right:1.8rem;color:var(--heading);background:color-mix(in srgb,var(--steel) 17%,#10161a);border-color:var(--rail-hi);border-top-color:var(--steel);transform:translateY(2px);box-shadow:inset 0 2px 0 var(--steel),inset 0 -8px 8px -8px #000,inset 0 3px 8px rgb(0 0 0/.45),0 0 0 0 #0000}
a.key[aria-current]::after{width:10px;height:10px;margin-top:-5px;border:0;background:var(--lamp-core);box-shadow:var(--lamp-glow)}
.key:active{transform:translateY(2px);box-shadow:inset 0 2px 4px rgb(0 0 0/.55)}
.head-add{min-height:2.9rem;padding:0 1.4rem 0 1.15rem;font-weight:700;letter-spacing:.005em;background:linear-gradient(180deg,color-mix(in srgb,var(--brand-hover) 70%,#fff) 0,var(--brand) 55%,color-mix(in srgb,var(--brand) 88%,#0a2a17) 100%);border-color:color-mix(in srgb,var(--brand) 70%,#fff);border-radius:4px;box-shadow:inset 0 1px 0 rgb(255 255 255/.55),0 3px 0 color-mix(in srgb,var(--brand) 42%,#04140a),0 0 0 1px color-mix(in srgb,var(--brand) 50%,transparent),0 0 18px -2px var(--ph-tight),0 10px 30px -8px color-mix(in srgb,var(--brand) 70%,transparent)}
.head-add:hover{transform:translateY(-1px);box-shadow:inset 0 1px 0 rgb(255 255 255/.6),0 4px 0 color-mix(in srgb,var(--brand) 42%,#04140a),0 0 0 1px color-mix(in srgb,var(--brand) 65%,transparent),0 0 22px -2px var(--ph-tight),0 12px 34px -8px color-mix(in srgb,var(--brand) 80%,transparent)}
.head-add:active{transform:translateY(3px);box-shadow:inset 0 2px 3px rgb(0 0 0/.3),0 0 0 1px color-mix(in srgb,var(--brand) 50%,transparent),0 0 12px -2px var(--ph-tight)}
.head-add .icon{width:1.1rem;height:1.1rem;stroke-width:2.4}
@media (prefers-reduced-motion:reduce){.head-add:hover,.head-add:active,.key:active,a.key[aria-current]{transform:none}}
@media (max-width:40rem){.key-row{display:flex}}
/* ---- type: body leading 1.55, reading measure capped at 66 characters ---- */
body{line-height:1.55}
.lede,.description,.lead,.why,.hint,.muted,.empty,.section-state,.panel>p,.card p,.said-text{line-height:1.55}
main p,.lede,.description,.lead,.why,.said-text,.capture>p,.hint{max-width:66ch}
.save-bar p,.glass-status,.keys-name,.crt-tube p,.margin-legend{max-width:none}

/* ---- glass: a track from her head to the box (Home) ----
   The rail drops from Vera's screen, turns, and meets the box at its question, ending in a lit lamp. */
.welcome-words{--tk:2.1rem;--pw:2.25rem;--tkc:color-mix(in srgb,var(--steel) 78%,var(--surface))}
.welcome-words>:is(.ask,.starters,.thread.brief){margin-left:var(--tk)}
.welcome-words>.brief-more{margin-left:calc(var(--tk) + 2.9rem)}
.welcome-words>.ask{position:relative}
.welcome-words>.speaker+.ask::before{content:"";position:absolute;box-sizing:border-box;left:calc(-1 * (var(--tk) - var(--pw) / 2 + 2.5px));width:calc(var(--tk) - var(--pw) / 2 + 2.5px);top:calc(-1rem - 1px);height:calc(1rem + 1px + 2.15rem);border-left:3px solid var(--tkc);border-bottom:3px solid var(--tkc);border-bottom-left-radius:14px;pointer-events:none}
.welcome-words>.speaker+.ask::after{content:"";position:absolute;left:-7px;top:calc(2.15rem - 6px);width:12px;height:12px;border-radius:50%;background:var(--lamp-core);box-shadow:0 0 0 3px #0a1214,var(--lamp-glow);pointer-events:none}
.welcome-words>.speaker .presence{box-shadow:0 0 0 3px color-mix(in srgb,var(--steel) 22%,transparent),0 0 18px -6px rgb(109 255 156/.6)}
@media(min-width:64rem){.welcome{grid-template-columns:minmax(0,1.55fr) minmax(21rem,1fr)}.welcome-words .ask-bar{gap:.6rem .8rem}}
@media(max-width:40rem){.welcome-words{--tk:1.8rem}}
@media(prefers-contrast:more){.welcome-words>.speaker+.ask::before{border-color:var(--ink)}}
@media(forced-colors:active){.welcome-words>.speaker+.ask::before{border-color:CanvasText}.welcome-words>.speaker+.ask::after{background:CanvasText;box-shadow:none}}

/* ---- list: overdue rows read "was due N days ago" in amber (To do, Home) ---- */
.stamp.was-due{display:block;line-height:1.15;color:var(--amber)}
.stamp.was-due .wd-was,.stamp.was-due .wd-ago{display:block}
.stamp.was-due .wd-was{font-size:.72rem;font-weight:500;opacity:.9}
.stamp.was-due .wd-ago{font-size:.8rem;font-weight:700;letter-spacing:-.005em}
@media(max-width:40rem){.stamp.was-due .wd-was,.stamp.was-due .wd-ago{display:inline}.stamp.was-due .wd-was::after{content:" "}}

/* ---- list: the Add key, wide and primary (To do, Plans) ---- */
.task-tools>details.panel.add-key,.add-key-panel{padding:0;background:none;border:0;box-shadow:none;margin-bottom:1rem}
.task-tools>details.panel.add-key{grid-column:1/-1}
.task-tools>.keyset{grid-column:1/-1}
.add-key>summary{display:flex;align-items:center;justify-content:center;gap:.6rem;box-sizing:border-box;width:100%;min-height:3rem;margin:0;padding:0 1.4rem;font:700 1rem/1 var(--sans);letter-spacing:.005em;color:var(--on-bright);background:linear-gradient(180deg,color-mix(in srgb,var(--brand-hover) 70%,#fff) 0,var(--brand) 55%,color-mix(in srgb,var(--brand) 88%,#0a2a17) 100%);border:1px solid color-mix(in srgb,var(--brand) 70%,#fff);border-radius:4px;box-shadow:inset 0 1px 0 rgb(255 255 255/.55),0 3px 0 color-mix(in srgb,var(--brand) 42%,#04140a),0 0 0 1px color-mix(in srgb,var(--brand) 50%,transparent),0 0 18px -2px var(--ph-tight),0 10px 30px -8px color-mix(in srgb,var(--brand) 70%,transparent);transition:transform .12s,box-shadow .12s}
.add-key>summary::before{content:none}
.add-key>summary .h2,.task-tools details.add-key.panel>summary .h2{font:inherit;letter-spacing:inherit;color:inherit;justify-content:center}
.add-key>summary .icon,.add-key>summary .h2 .icon,.panel>summary>.icon{width:1.15rem;height:1.15rem;stroke-width:2.4;color:inherit}
.add-key>summary:hover{transform:translateY(-1px)}
.add-key>summary:active{transform:translateY(3px);box-shadow:inset 0 2px 3px rgb(0 0 0/.3),0 0 0 1px color-mix(in srgb,var(--brand) 50%,transparent),0 0 12px -2px var(--ph-tight)}
.add-key>summary:focus-visible{outline:2px solid var(--brand);outline-offset:4px}
.task-tools>details.panel.add-key[open],.add-key-panel>details.add-key[open]{padding:0 0 1.2rem;background:var(--plate);border:1px solid var(--plate-edge);border-radius:var(--sq);box-shadow:var(--shadow)}
.add-key[open]>summary{margin-bottom:1.1rem;border-bottom-left-radius:0;border-bottom-right-radius:0}
.add-key[open]>:not(summary){margin-left:1.2rem;margin-right:1.2rem}
.add-key-panel>.add-key[open]{padding-bottom:.6rem}
@media(prefers-reduced-motion:reduce){.add-key>summary:hover,.add-key>summary:active{transform:none}}

/* ---- list: the keycap tray carried to Plans (List/Month and the month's Earlier/Later) ---- */
.page-head .tabs.key-row{margin:0}
.month-nav.key-row{margin:0;flex-wrap:nowrap;gap:.25rem}
.month-nav a.key{padding-right:.85rem}
.month-nav a.key::after{content:none}
.month-nav a.key:last-child{padding-left:.85rem}
